#include "protocol/codec.h"

#include <array>
#include <fstream>
#include <string>
#include <vector>

#include "protocol/framing.h"
#include "test_support.h"

/** Decode Python-generated bytes, then verify bounded application validation. */
int main(int argc, char** argv) {
  auto power = makeCommand("power");
  power.envelope.which_body = info_tv_v1_Envelope_power_settings_tag;
  power.envelope.body.power_settings.lock_action = info_tv_v1_LockAction_LOCK_ACTION_DEEP_SLEEP;
  power.envelope.body.power_settings.session_locked = true;
  power.envelope.body.power_settings.unlock_poll_seconds = 5;
  CHECK(!info_tv::validateCommand(power.envelope));
  power.envelope.body.power_settings.unlock_poll_seconds = 3601;
  CHECK(info_tv::validateCommand(power.envelope));
  power.envelope.body.power_settings.unlock_poll_seconds = 5;
  power.envelope.body.power_settings.lock_action = info_tv_v1_LockAction_LOCK_ACTION_NONE;
  CHECK(info_tv::validateCommand(power.envelope));
  power.envelope.body.power_settings.unlock_poll_seconds = 0;
  CHECK(!info_tv::validateCommand(power.envelope));
  power.envelope.body.power_settings.lock_action = static_cast<info_tv_v1_LockAction>(3);
  CHECK(info_tv::validateCommand(power.envelope));
  CHECK(argc == 2);
  std::ifstream input(std::string(argv[1]) + "/status_frame.hex");
  CHECK(input.good());
  std::string hex;
  input >> hex;
  info_tv::FrameDecoder decoder;
  bool decoded = false;
  for (size_t index = 0; index < hex.size(); index += 2) {
    const auto byte = static_cast<uint8_t>(std::stoul(hex.substr(index, 2), nullptr, 16));
    if (decoder.feed(byte)) decoded = true;
  }
  CHECK(decoded);
  info_tv::Envelope envelope{};
  CHECK(info_tv::decodeEnvelope(decoder.data(), decoder.size(), envelope));
  CHECK(!info_tv::validateCommand(envelope));
  CHECK(envelope.which_body == info_tv_v1_Envelope_card_upsert_tag);
  CHECK(envelope.body.card_upsert.card.view.content.status.progress_percent == 42);
  CHECK(envelope.body.card_upsert.card.view.icon == info_tv_v1_TaskIcon_TASK_ICON_TASK);
  envelope.body.card_upsert.card.view.icon = info_tv_v1_TaskIcon_TASK_ICON_TEST;
  envelope.body.card_upsert.card.view.content.status.recent_question_seconds = 30;
  std::array<uint8_t, 4096> encoded{};
  const auto size = info_tv::encodeEnvelope(envelope, encoded.data(), encoded.size());
  info_tv::Envelope roundtrip{};
  CHECK(info_tv::decodeEnvelope(encoded.data(), size, roundtrip));
  CHECK(info_tv::sameCard(envelope.body.card_upsert.card, roundtrip.body.card_upsert.card));
  envelope.body.card_upsert.card.view.content.status.recent_question_seconds = 31;
  CHECK(info_tv::validateCommand(envelope));
  CHECK(!info_tv::sameCard(envelope.body.card_upsert.card, roundtrip.body.card_upsert.card));
  envelope.body.card_upsert.card.view.content.status.recent_question_seconds = 30;
  envelope.body.card_upsert.card.view.content.status.progress_percent = 101;
  CHECK(info_tv::validateCommand(envelope));
  auto invalid = makeSnapshot();
  invalid.envelope.body.snapshot.cards_count = 2;
  invalid.envelope.body.snapshot.cards[1] = invalid.envelope.body.snapshot.cards[0];
  CHECK(info_tv::validateCommand(invalid.envelope));
  auto note = makeNotification("zero");
  note.envelope.body.notification.has_display_duration_ms = true;
  note.envelope.body.notification.display_duration_ms = 0;
  CHECK(info_tv::validateCommand(note.envelope));

  // The worst-case eight-card snapshot, including metadata, fits one wire frame.
  auto maximum = makeSnapshot("maximum");
  auto& cards = maximum.envelope.body.snapshot;
  cards.has_weather = true;
  cards.weather.has_temperature_c = true;
  cards.weather.temperature_c = -100;
  cards.weather.condition = info_tv_v1_WeatherCondition_WEATHER_CONDITION_STORM;
  cards.weather.valid_for_ms = 3600000;
  cards.weather.has_daily_low_c = cards.weather.has_daily_high_c = true;
  cards.weather.daily_low_c = -100;
  cards.weather.daily_high_c = 100;
  std::memset(cards.weather.location, 'w', sizeof(cards.weather.location) - 1);
  cards.cards_count = 8;
  for (size_t index = 0; index < 8; ++index) {
    cards.cards[index] = makeCard();
    auto& card = cards.cards[index];
    std::memset(card.card_id, 'a' + index, sizeof(card.card_id) - 1);
    card.revision = UINT64_MAX;
    auto& view = card.view;
    view.icon = info_tv_v1_TaskIcon_TASK_ICON_DEPLOY;
    std::memset(view.title, 't', sizeof(view.title) - 1);
    std::memset(view.source, 's', sizeof(view.source) - 1);
    std::memset(view.context, 'c', sizeof(view.context) - 1);
    std::memset(view.content.status.text, 'x', sizeof(view.content.status.text) - 1);
    std::memset(view.content.status.detail, 'd', sizeof(view.content.status.detail) - 1);
    view.content.status.progress_percent = 100;
    view.content.status.recent_question_seconds = 30;
  }
  static_assert(info_tv_v1_Envelope_size <= 4096);
  const auto maximumSize = info_tv::encodeEnvelope(maximum.envelope, encoded.data(), encoded.size());
  CHECK(maximumSize > 0 && maximumSize <= 4096);
  CHECK(info_tv::decodeEnvelope(encoded.data(), maximumSize, roundtrip));
  CHECK(!info_tv::validateCommand(roundtrip));
  CHECK(roundtrip.body.snapshot.cards_count == 8);
  CHECK(roundtrip.body.snapshot.weather.temperature_c == -100);
  CHECK(roundtrip.body.snapshot.weather.has_daily_low_c);
  CHECK(roundtrip.body.snapshot.weather.daily_low_c == -100);
  CHECK(roundtrip.body.snapshot.weather.daily_high_c == 100);
  auto weather = makeCommand("weather");
  weather.envelope.which_body = info_tv_v1_Envelope_weather_tag;
  CHECK(!info_tv::validateCommand(weather.envelope));  // Explicit clear.
  weather.envelope.body.weather = cards.weather;
  CHECK(!info_tv::validateCommand(weather.envelope));
  weather.envelope.body.weather.temperature_c = 101;
  CHECK(info_tv::validateCommand(weather.envelope));
  weather.envelope.body.weather = cards.weather;
  weather.envelope.body.weather.valid_for_ms = 0;
  CHECK(info_tv::validateCommand(weather.envelope));
  weather.envelope.body.weather = cards.weather;
  weather.envelope.body.weather.condition = static_cast<info_tv_v1_WeatherCondition>(7);
  CHECK(info_tv::validateCommand(weather.envelope));
  weather.envelope.body.weather = cards.weather;
  weather.envelope.body.weather.has_daily_low_c = false;
  CHECK(info_tv::validateCommand(weather.envelope));
  weather.envelope.body.weather = cards.weather;
  weather.envelope.body.weather.daily_low_c = 10;
  weather.envelope.body.weather.daily_high_c = 0;
  CHECK(info_tv::validateCommand(weather.envelope));
  auto alert = makeWeatherAlert();
  CHECK(!info_tv::validateCommand(alert.envelope));
  const auto alertSize = info_tv::encodeEnvelope(alert.envelope, encoded.data(), encoded.size());
  CHECK(info_tv::decodeEnvelope(encoded.data(), alertSize, roundtrip));
  CHECK(roundtrip.body.weather_alert.notify);
  CHECK(!std::strcmp(roundtrip.body.weather_alert.source, "Demo bureau"));
  alert.envelope.body.weather_alert.valid_for_ms = 86400001;
  CHECK(info_tv::validateCommand(alert.envelope));
  alert.envelope.body.weather_alert = {};
  CHECK(!info_tv::validateCommand(alert.envelope));
  alert.envelope.body.weather_alert.notify = true;
  CHECK(info_tv::validateCommand(alert.envelope));
  auto metadata = makeCard();
  auto changed = metadata;
  std::strcpy(changed.view.context, "different-project");
  CHECK(!info_tv::sameCard(metadata, changed));
  changed = metadata;
  changed.view.icon = info_tv_v1_TaskIcon_TASK_ICON_CODE;
  CHECK(!info_tv::sameCard(metadata, changed));
  auto unknown = makeSnapshot();
  unknown.envelope.body.snapshot.cards[0].view.icon = static_cast<info_tv_v1_TaskIcon>(6);
  CHECK(info_tv::validateCommand(unknown.envelope));

  // Zero must survive both the setting and Applied-feedback presence bits.
  auto setting = makeCommand("brightness");
  setting.envelope.which_body = info_tv_v1_Envelope_device_settings_tag;
  setting.envelope.body.device_settings.has_brightness_percent = true;
  CHECK(!info_tv::validateCommand(setting.envelope));
  auto settingsSize = info_tv::encodeEnvelope(setting.envelope, encoded.data(), encoded.size());
  CHECK(info_tv::decodeEnvelope(encoded.data(), settingsSize, roundtrip));
  CHECK(roundtrip.body.device_settings.has_brightness_percent);
  CHECK(roundtrip.body.device_settings.brightness_percent == 0);
  setting.envelope.which_body = info_tv_v1_Envelope_acknowledgment_tag;
  setting.envelope.body.acknowledgment = info_tv_v1_Acknowledgment{};
  auto& ack = setting.envelope.body.acknowledgment;
  std::strcpy(ack.in_reply_to, "brightness");
  ack.stage = info_tv_v1_AckStage_ACK_STAGE_APPLIED;
  ack.has_brightness_percent = true;
  settingsSize = info_tv::encodeEnvelope(setting.envelope, encoded.data(), encoded.size());
  CHECK(info_tv::decodeEnvelope(encoded.data(), settingsSize, roundtrip));
  CHECK(roundtrip.body.acknowledgment.stage == info_tv_v1_AckStage_ACK_STAGE_APPLIED);
  CHECK(roundtrip.body.acknowledgment.has_brightness_percent);
  CHECK(roundtrip.body.acknowledgment.brightness_percent == 0);
}
